import { Component, OnInit, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { AuthService } from '../../../core/services/auth.service';
import { OfflinePreparacionService } from '../servicios/offline-preparacion.service';

interface EstadoPreparacion {
  estado: 'no-preparado' | 'preparando' | 'preparado' | 'error';
  mensaje: string;
  fechaUltimaActualizacion?: string;
}

interface Sucursal {
  id: number;
  nombre: string;
}

@Component({
  selector: 'app-preparar-offline',
  standalone: true,
  imports: [CommonModule, FormsModule],
  template: `
    <div class="offline-container">
      <div class="offline-card">
        <h2>Preparar información para operación offline</h2>

        <div class="form-group">
          <label for="sucursal">Sucursal</label>
          <select
            id="sucursal"
            [(ngModel)]="sucursalSeleccionada"
            [disabled]="cargandoSucursales || estado.estado === 'preparando'"
            class="form-control"
          >
            <option [value]="">-- Seleccionar sucursal --</option>
            <option *ngFor="let sucursal of sucursales" [value]="sucursal.id">
              {{ sucursal.nombre }}
            </option>
          </select>
        </div>

        <div class="estado-box">
          <div class="estado-item">
            <span class="label">Estado actual:</span>
            <span [ngClass]="'estado-' + estado.estado">
              {{ getEstadoTexto() }}
            </span>
          </div>

          <div *ngIf="estado.fechaUltimaActualizacion" class="estado-item">
            <span class="label">Última actualización:</span>
            <span>{{ estado.fechaUltimaActualizacion | date : 'dd/MM/yyyy HH:mm' }}</span>
          </div>

          <div *ngIf="estado.estado === 'preparado'" class="estado-item success">
            Información disponible localmente
          </div>
        </div>

        <div *ngIf="estado.estado === 'error'" class="mensaje-error">
          {{ estado.mensaje }}
        </div>

        <div *ngIf="estado.estado === 'preparando'" class="progreso">
          <div class="spinner"></div>
          <p>Descargando información...</p>
        </div>

        <button
          (click)="prepararInformacion()"
          [disabled]="
            !sucursalSeleccionada ||
            estado.estado === 'preparando' ||
            cargandoSucursales
          "
          class="btn btn-primary"
        >
          {{ estado.estado === 'preparando' ? 'Preparando...' : 'Preparar información' }}
        </button>

        <button
          *ngIf="estado.estado === 'preparado'"
          (click)="reintentar()"
          class="btn btn-secondary"
        >
          Actualizar
        </button>
      </div>
    </div>
  `,
  styles: [
    `
      .offline-container {
        padding: 2rem;
        max-width: 600px;
        margin: 0 auto;
      }

      .offline-card {
        background: white;
        border-radius: 8px;
        padding: 2rem;
        box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
      }

      h2 {
        margin-top: 0;
        margin-bottom: 1.5rem;
        color: #333;
        font-size: 1.5rem;
      }

      .form-group {
        margin-bottom: 1.5rem;
      }

      label {
        display: block;
        margin-bottom: 0.5rem;
        font-weight: 500;
        color: #555;
      }

      .form-control {
        width: 100%;
        padding: 0.75rem;
        border: 1px solid #ddd;
        border-radius: 4px;
        font-size: 1rem;
        font-family: inherit;
      }

      .form-control:disabled {
        background-color: #f5f5f5;
        cursor: not-allowed;
      }

      .form-control:focus {
        outline: none;
        border-color: #1976d2;
        box-shadow: 0 0 0 3px rgba(25, 118, 210, 0.1);
      }

      .estado-box {
        background: #f9f9f9;
        border-left: 4px solid #1976d2;
        padding: 1rem;
        margin: 1.5rem 0;
        border-radius: 4px;
      }

      .estado-item {
        display: flex;
        justify-content: space-between;
        margin-bottom: 0.75rem;
        font-size: 0.95rem;
      }

      .estado-item:last-child {
        margin-bottom: 0;
      }

      .label {
        font-weight: 500;
        color: #666;
      }

      .estado-no-preparado {
        color: #ff9800;
        font-weight: 600;
      }

      .estado-preparando {
        color: #2196f3;
        font-weight: 600;
      }

      .estado-preparado {
        color: #4caf50;
        font-weight: 600;
      }

      .estado-error {
        color: #f44336;
        font-weight: 600;
      }

      .estado-item.success {
        color: #4caf50;
        font-weight: 500;
        margin-top: 0.75rem;
      }

      .mensaje-error {
        background: #ffebee;
        color: #c62828;
        padding: 1rem;
        border-radius: 4px;
        margin: 1rem 0;
        border-left: 4px solid #c62828;
      }

      .progreso {
        text-align: center;
        padding: 2rem 0;
      }

      .spinner {
        width: 40px;
        height: 40px;
        margin: 0 auto 1rem;
        border: 4px solid #f3f3f3;
        border-top: 4px solid #1976d2;
        border-radius: 50%;
        animation: spin 1s linear infinite;
      }

      @keyframes spin {
        0% {
          transform: rotate(0deg);
        }
        100% {
          transform: rotate(360deg);
        }
      }

      .btn {
        width: 100%;
        padding: 0.75rem 1.5rem;
        font-size: 1rem;
        border: none;
        border-radius: 4px;
        cursor: pointer;
        font-weight: 500;
        transition: all 0.3s ease;
        margin-top: 1rem;
      }

      .btn:first-of-type {
        margin-top: 0;
      }

      .btn-primary {
        background: #1976d2;
        color: white;
      }

      .btn-primary:hover:not(:disabled) {
        background: #1565c0;
      }

      .btn-primary:disabled {
        background: #bdbdbd;
        cursor: not-allowed;
      }

      .btn-secondary {
        background: #757575;
        color: white;
        margin-top: 0.5rem;
      }

      .btn-secondary:hover {
        background: #616161;
      }

      @media (max-width: 768px) {
        .offline-container {
          padding: 1rem;
        }

        .offline-card {
          padding: 1.5rem;
        }

        h2 {
          font-size: 1.25rem;
        }
      }
    `,
  ],
})
export class PrepararOfflineComponent implements OnInit {
  private authService = inject(AuthService);
  private offlinePreparacionService = inject(OfflinePreparacionService);

  sucursales: Sucursal[] = [];
  sucursalSeleccionada: number | '' = '';
  cargandoSucursales = false;

  estado: EstadoPreparacion = {
    estado: 'no-preparado',
    mensaje: '',
  };

  ngOnInit(): void {
    this.cargarSucursales();
    this.verificarPreparacionExistente();
  }

  private cargarSucursales(): void {
    this.cargandoSucursales = true;
    this.offlinePreparacionService.obtenerSucursales().subscribe({
      next: (sucursales: Sucursal[]) => {
        this.sucursales = sucursales;
        this.cargandoSucursales = false;
      },
      error: (error: unknown) => {
        console.error('Error al cargar sucursales:', error);
        this.estado = {
          estado: 'error',
          mensaje: 'No se pudieron cargar las sucursales',
        };
        this.cargandoSucursales = false;
      },
    });
  }

  private async verificarPreparacionExistente(): Promise<void> {
    const usuario = this.authService.usuario();
    if (!usuario || !usuario.empresa_id) {
      return;
    }

    const empresaId = usuario.empresa_id;

    // Si hay sucursal seleccionada, verificar si existe preparación
    if (this.sucursalSeleccionada && typeof this.sucursalSeleccionada === 'number') {
      const preparacion = await this.offlinePreparacionService.obtenerPreparacion(
        empresaId,
        this.sucursalSeleccionada,
      );

      if (preparacion) {
        this.estado = {
          estado: 'preparado',
          mensaje: '',
          fechaUltimaActualizacion: preparacion.metadata.fecha_preparacion,
        };
      }
    }
  }

  async prepararInformacion(): Promise<void> {
    if (!this.sucursalSeleccionada || typeof this.sucursalSeleccionada !== 'number') {
      this.estado = {
        estado: 'error',
        mensaje: 'Selecciona una sucursal',
      };
      return;
    }

    const usuario = this.authService.usuario();
    if (!usuario || !usuario.empresa_id) {
      this.estado = {
        estado: 'error',
        mensaje: 'No se pudo obtener la información del usuario',
      };
      return;
    }

    // Verificar si hay conexión a Internet
    if (!navigator.onLine) {
      this.estado = {
        estado: 'error',
        mensaje: 'Se necesita conexión a Internet para preparar o actualizar la información offline.',
      };
      return;
    }

    this.estado = {
      estado: 'preparando',
      mensaje: 'Descargando información...',
    };

    try {
      const preparacion = await this.offlinePreparacionService
        .prepararInformacion(this.sucursalSeleccionada)
        .toPromise();

      if (!preparacion) {
        throw new Error('No se recibió respuesta del servidor');
      }

      // Guardar en IndexedDB
      const guardado = await this.offlinePreparacionService.guardarPreparacion(
        preparacion,
        usuario.empresa_id,
      );

      if (!guardado) {
        throw new Error('No se pudo guardar la información en el almacenamiento local');
      }

      // Actualizar estado
      this.estado = {
        estado: 'preparado',
        mensaje: '',
        fechaUltimaActualizacion: preparacion.metadata.fecha_preparacion,
      };
    } catch (error) {
      console.error('Error al preparar información:', error);

      // Mantener la última preparación válida si la descarga falla
      const preparacionAnterior = await this.offlinePreparacionService.obtenerPreparacion(
        usuario.empresa_id,
        this.sucursalSeleccionada,
      );

      if (preparacionAnterior) {
        // Hay una preparación anterior válida
        this.estado = {
          estado: 'error',
          mensaje: 'Error al actualizar. Se conserva la última preparación válida.',
          fechaUltimaActualizacion: preparacionAnterior.metadata.fecha_preparacion,
        };
      } else {
        // No hay preparación anterior
        this.estado = {
          estado: 'error',
          mensaje:
            (error instanceof Error ? error.message : 'Error desconocido') ||
            'Error al preparar la información. Intenta nuevamente.',
        };
      }
    }
  }

  getEstadoTexto(): string {
    switch (this.estado.estado) {
      case 'no-preparado':
        return 'No preparado';
      case 'preparando':
        return 'Preparando...';
      case 'preparado':
        return '✓ Preparado';
      case 'error':
        return 'Error';
      default:
        return '';
    }
  }

  reintentar(): void {
    this.prepararInformacion();
  }
}
